import json

# ---------------------------------------------------------------------------
# Helpers for reading the snapshot defensively
# ---------------------------------------------------------------------------

_RESULT_TYPES = {
    "1": "successful",
    "2": "failed",
    "3": "stopped",
    "4": "retried",
    "5": "max_retries_exceeded",
}

# Registry key prefixes and the name a user of rq would use for each.
_REGISTRIES = (
    ("rq:wip:", "started"),
    ("rq:finished:", "finished"),
    ("rq:failed:", "failed"),
    ("rq:deferred:", "deferred"),
    ("rq:scheduled:", "scheduled"),
    ("rq:canceled:", "canceled"),
)

# The registry that a job with a given status is expected to be in.
_REGISTRY_FOR_STATUS = {
    "started": "started",
    "finished": "finished",
    "failed": "failed",
    "stopped": "failed",
    "deferred": "deferred",
    "scheduled": "scheduled",
    "canceled": "canceled",
}

# The statuses allowed for a job found in a given registry.
# "queued" is allowed in the started registry because a worker registers
# the execution before it marks the job as started.
_STATUSES_FOR_REGISTRY = {
    "started": ("started", "queued"),
    "finished": ("finished",),
    "failed": ("failed", "stopped"),
    "deferred": ("deferred",),
    "scheduled": ("scheduled",),
    "canceled": ("canceled",),
}


def _str(x):
    if isinstance(x, str):
        return x
    if x is None:
        return ""
    return str(x)


def _int(x):
    try:
        return int(_str(x))
    except Exception:
        return None


def _members(v):
    """Members of a set, list or zset value, as strings."""
    out = []
    if not isinstance(v, list):
        return out
    for item in v:
        if isinstance(item, (list, tuple)):
            if item:
                out.append(_str(item[0]))
        elif item is not None:
            out.append(_str(item))
    return out


def _unique(seq):
    seen = set()
    out = []
    for x in seq:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out


def _parse(snap):
    m = {
        "job_hashes": {},
        "dependents": {},
        "dependency_sets": {},
        "queue_lists": {},
        "picked_up_lists": {},
        "registries": {name: {} for _, name in _REGISTRIES},
        "execution_hashes": {},
        "execution_registries": {},
        "results": {},
        "workers": {},
        "known_queues": set(),
        "groups": {},
    }
    if not isinstance(snap, dict):
        return m

    for key in sorted(k for k in snap if isinstance(k, str)):
        e = snap.get(key)
        if not isinstance(e, dict):
            continue
        t = e.get("t")
        v = e.get("v")

        if key.startswith("rq:job:"):
            rest = key[len("rq:job:"):]
            if t == "hash" and rest and ":" not in rest:
                m["job_hashes"][rest] = v if isinstance(v, dict) else {}
            elif t == "set" and rest.startswith(":") and rest.endswith(":dependencies"):
                jid = rest[1:-len(":dependencies")]
                if jid:
                    m["dependency_sets"][jid] = set(_members(v))
            elif t == "set" and rest.endswith(":dependents"):
                jid = rest[:-len(":dependents")]
                if jid and ":" not in jid:
                    m["dependents"][jid] = set(_members(v))
            continue

        if key == "rq:queues" and t == "set":
            for q in _members(v):
                m["known_queues"].add(q[len("rq:queue:"):] if q.startswith("rq:queue:") else q)
            continue

        if key.startswith("rq:queue:") and t == "list":
            rest = key[len("rq:queue:"):]
            if rest.endswith(":intermediate"):
                m["picked_up_lists"][rest[:-len(":intermediate")]] = _members(v)
            else:
                m["queue_lists"][rest] = _members(v)
            continue

        matched = False
        for prefix, name in _REGISTRIES:
            if key.startswith(prefix) and t == "zset":
                qname = key[len(prefix):]
                ids = _members(v)
                if name == "started":
                    ids = [i.split(":", 1)[0] for i in ids]
                m["registries"][name][qname] = _unique(ids)
                matched = True
                break
        if matched:
            continue

        if key.startswith("rq:executions:") and t == "zset":
            m["execution_registries"][key[len("rq:executions:"):]] = _members(v)
            continue

        if key.startswith("rq:execution:") and t == "hash":
            rest = key[len("rq:execution:"):]
            if ":" in rest:
                jid, eid = rest.split(":", 1)
                m["execution_hashes"].setdefault(jid, {})[eid] = v if isinstance(v, dict) else {}
            continue

        if key.startswith("rq:results:") and t == "stream":
            m["results"][key[len("rq:results:"):]] = [x for x in v if isinstance(x, dict)] if isinstance(v, list) else []
            continue

        if key.startswith("rq:worker:") and t == "hash":
            m["workers"][key[len("rq:worker:"):]] = v if isinstance(v, dict) else {}
            continue

        if key.startswith("rq:group:") and t == "set":
            m["groups"][key[len("rq:group:"):]] = sorted(_members(v))
            continue

    return m


def _complete_jobs(m):
    """Jobs that rq can actually load (a hash that has the job payload)."""
    return {jid: h for jid, h in m["job_hashes"].items() if "data" in h}


def _status(h):
    return _str(h.get("status")) or "created"


def _depends_on(m, jid, h):
    deps = []
    raw = h.get("dependency_ids")
    if raw:
        try:
            parsed = json.loads(_str(raw))
            if isinstance(parsed, list):
                deps = [_str(x) for x in parsed]
        except Exception:
            deps = []
    if not deps and h.get("dependency_id"):
        deps = [_str(h.get("dependency_id"))]
    if not deps:
        deps = sorted(m["dependency_sets"].get(jid, set()))
    return _unique(deps)


def _is_repeating(h):
    return bool(h.get("repeats_left")) or bool(h.get("repeat_intervals"))


def _result_view(r):
    out = {
        "type": _RESULT_TYPES.get(_str(r.get("type")), "type_" + _str(r.get("type"))),
        "worker": _str(r.get("worker_name")) or None,
    }
    if r.get("return_value") not in (None, ""):
        out["return_value"] = _str(r.get("return_value"))
    if r.get("exc_string") not in (None, ""):
        out["error"] = _str(r.get("exc_string"))
    return out


def _places(m):
    """For every job id: the set of (place, queue) where it is listed."""
    places = {}
    for q, ids in m["queue_lists"].items():
        for jid in ids:
            places.setdefault(jid, set()).add(("waiting", q))
    for q, ids in m["picked_up_lists"].items():
        for jid in ids:
            places.setdefault(jid, set()).add(("being_picked_up", q))
    for name, per_queue in m["registries"].items():
        for q, ids in per_queue.items():
            for jid in ids:
                places.setdefault(jid, set()).add((name, q))
    return places


def _in(m, place, queue, jid):
    if place == "waiting":
        return jid in m["queue_lists"].get(queue, [])
    if place == "being_picked_up":
        return jid in m["picked_up_lists"].get(queue, [])
    return jid in m["registries"].get(place, {}).get(queue, [])


# ---------------------------------------------------------------------------
# Abstraction function
# ---------------------------------------------------------------------------

def abstract(snap: dict) -> dict:
    """Business-level state, as {variable name: JSON-serialisable value}."""
    m = _parse(snap)
    jobs_raw = _complete_jobs(m)

    # --- jobs ---
    jobs = {}
    for jid in sorted(jobs_raw):
        h = jobs_raw[jid]
        executions = []
        eids = set(m["execution_hashes"].get(jid, {}).keys())
        for eid in sorted(eids):
            eh = m["execution_hashes"][jid][eid]
            executions.append({"id": eid, "worker": _str(eh.get("worker_name")) or None})
        job_entry = snap.get("rq:job:" + jid) if isinstance(snap, dict) else None
        jobs[jid] = {
            "status": _status(h),
            "queue": _str(h.get("origin")) or None,
            "description": _str(h.get("description")) or None,
            "worker": _str(h.get("worker_name")) or None,
            "enqueued_at": _str(h.get("enqueued_at")) or None,
            "started_at": _str(h.get("started_at")) or None,
            "ended_at": _str(h.get("ended_at")) or None,
            "depends_on": _depends_on(m, jid, h),
            "dependents": sorted(m["dependents"].get(jid, set())),
            "group": _str(h.get("group_id")) or None,
            "retries_left": _int(h.get("retries_left")) if h.get("retries_left") else None,
            "number_of_retries": _int(h.get("number_of_retries")) if h.get("number_of_retries") else None,
            "repeats_left": _int(h.get("repeats_left")) if h.get("repeats_left") else None,
            "will_expire": bool(job_entry.get("ttl")) if isinstance(job_entry, dict) else False,
            "results": [_result_view(r) for r in m["results"].get(jid, [])],
            "executions": executions,
        }

    # --- queues ---
    names = set(m["known_queues"]) | set(m["queue_lists"]) | set(m["picked_up_lists"])
    for per_queue in m["registries"].values():
        names |= set(per_queue)
    for h in jobs_raw.values():
        if h.get("origin"):
            names.add(_str(h.get("origin")))

    queues = {}
    for q in sorted(names):
        entry = {
            "waiting": [j for j in m["queue_lists"].get(q, []) if j in jobs_raw],
            "being_picked_up": [j for j in m["picked_up_lists"].get(q, []) if j in jobs_raw],
        }
        for _, reg in _REGISTRIES:
            entry[reg] = sorted(j for j in set(m["registries"][reg].get(q, [])) if j in jobs_raw)
        queues[q] = entry

    # --- workers ---
    workers = {}
    for name in sorted(m["workers"]):
        h = m["workers"][name]
        w = {
            "state": _str(h.get("state")) or None,
            "current_job": _str(h.get("current_job")) or None,
            "successful_jobs": _int(h.get("successful_job_count")) or 0,
            "failed_jobs": _int(h.get("failed_job_count")) or 0,
        }
        if h.get("queues"):
            w["queues"] = [q for q in _str(h.get("queues")).split(",") if q]
        workers[name] = w

    out = {"queues": queues, "jobs": jobs, "workers": workers}
    if m["groups"]:
        out["groups"] = {g: [j for j in ids if j in jobs_raw] for g, ids in sorted(m["groups"].items())}
    return out


# ---------------------------------------------------------------------------
# Business invariants
# ---------------------------------------------------------------------------

def invariants(snap: dict) -> dict:
    """Business invariants, as {invariant name: bool}; True means it holds."""
    m = _parse(snap)
    jobs = _complete_jobs(m)
    places = _places(m)

    def status_of(jid):
        return _status(jobs[jid]) if jid in jobs else None

    def origin_of(jid):
        return _str(jobs[jid].get("origin")) if jid in jobs else ""

    inv = {}

    # Every stored job record can be loaded (no half-written job fragments).
    inv["every_job_record_is_complete"] = all("data" in h for h in m["job_hashes"].values())

    # Jobs waiting in a queue are queued, and belong to that queue.
    ok_status = True
    ok_origin = True
    for q, ids in list(m["queue_lists"].items()) + list(m["picked_up_lists"].items()):
        for jid in ids:
            if jid not in jobs:
                continue
            if q in m["queue_lists"] and jid in m["queue_lists"][q] and status_of(jid) != "queued":
                ok_status = False
            if origin_of(jid) and origin_of(jid) != q:
                ok_origin = False
    inv["waiting_jobs_are_queued"] = ok_status
    inv["jobs_in_a_queue_belong_to_that_queue"] = ok_origin

    # A queued job is waiting in its queue (or being picked up by a worker).
    ok = True
    for jid, h in jobs.items():
        if _status(h) != "queued":
            continue
        q = origin_of(jid)
        if not (_in(m, "waiting", q, jid) or _in(m, "being_picked_up", q, jid) or _in(m, "started", q, jid)):
            ok = False
    inv["queued_jobs_are_in_their_queue"] = ok

    # Every status has its matching registry in the job's queue.
    for status, reg in (
        ("started", "started"),
        ("finished", "finished"),
        ("failed", "failed"),
        ("deferred", "deferred"),
        ("scheduled", "scheduled"),
        ("canceled", "canceled"),
    ):
        ok = True
        for jid, h in jobs.items():
            st = _status(h)
            if _REGISTRY_FOR_STATUS.get(st) != reg or (reg == "failed" and st not in ("failed", "stopped")):
                continue
            if reg != _REGISTRY_FOR_STATUS.get(status) or st not in (status,) + (("stopped",) if status == "failed" else ()):
                continue
            if not _in(m, reg, origin_of(jid), jid):
                ok = False
        inv[status + ("_and_stopped" if status == "failed" else "") + "_jobs_are_in_" + reg + "_registry"] = ok

    # Every job in a registry has the matching status.
    ok = True
    for reg, per_queue in m["registries"].items():
        for q, ids in per_queue.items():
            for jid in ids:
                if jid not in jobs:
                    continue
                if reg == "finished" and _is_repeating(jobs[jid]):
                    continue
                if status_of(jid) not in _STATUSES_FOR_REGISTRY[reg]:
                    ok = False
                if origin_of(jid) and origin_of(jid) != q:
                    ok = False
    inv["registry_members_have_matching_status"] = ok

    # A job is in exactly one place at a time.
    ok = True
    for jid, ps in places.items():
        if jid not in jobs:
            continue
        kinds = set()
        for kind, _q in ps:
            if kind in ("being_picked_up", "started"):
                kind = "in_progress"
            if kind == "finished" and _is_repeating(jobs[jid]):
                continue
            kinds.add(kind)
        if len(kinds) > 1:
            ok = False
    inv["each_job_is_in_one_place"] = ok

    # A started job is assigned to a worker.
    inv["started_jobs_have_a_worker"] = all(
        _str(h.get("worker_name")) != "" for h in jobs.values() if _status(h) == "started"
    )

    # A worker's current job is started and assigned to that worker.
    ok = True
    current = {}
    for wname, wh in m["workers"].items():
        cj = _str(wh.get("current_job"))
        if not cj:
            continue
        current.setdefault(cj, []).append(wname)
        if cj in jobs:
            if status_of(cj) != "started" or _str(jobs[cj].get("worker_name")) != wname:
                ok = False
    inv["workers_current_job_is_started_by_them"] = ok
    inv["no_job_is_run_by_two_workers"] = all(len(ws) <= 1 for ws in current.values())

    # Only running jobs have live executions.
    ok = True
    for jid, execs in m["execution_hashes"].items():
        if not execs:
            continue
        if jid not in jobs or status_of(jid) not in ("started", "queued"):
            ok = False
    for q, ids in m["registries"]["started"].items():
        for jid in ids:
            if jid not in jobs or status_of(jid) not in ("started", "queued"):
                ok = False
    inv["only_running_jobs_have_executions"] = ok

    # Results agree with the outcome.
    ok_fin = True
    ok_fail = True
    for jid, h in jobs.items():
        res = m["results"].get(jid) or []
        if not res:
            continue
        latest = _RESULT_TYPES.get(_str(res[-1].get("type")), "")
        st = _status(h)
        if st == "finished" and latest != "successful":
            ok_fin = False
        if st in ("failed", "stopped") and latest in ("successful", "retried"):
            ok_fail = False
    inv["finished_jobs_latest_result_is_successful"] = ok_fin
    inv["failed_jobs_latest_result_is_a_failure"] = ok_fail

    # Dependents recorded on a job really depend on it.
    ok = True
    for parent, deps in m["dependents"].items():
        for child in deps:
            if child in jobs and parent not in _depends_on(m, child, jobs[child]):
                ok = False
    inv["dependents_depend_on_their_parent"] = ok

    # Every queue in use is a registered queue.
    used = set(m["queue_lists"]) | set(m["picked_up_lists"])
    used |= {origin_of(j) for j in jobs if origin_of(j)}
    inv["every_queue_in_use_is_registered"] = used <= m["known_queues"]

    return inv
